//! Provisional xcvu3p.json regression test: the file the generator
//! builds must load, validate, and resolve BELs, and must stay
//! provisional with every derived value flagged.
//!
//! The file is generated by `scripts/gen_xcvu3p.py` from the xcku3p
//! template plus AMD XMP103 counts. It is NOT Vivado-confirmed: the
//! frame total it computes (73,035) overshoots UG570 Table 1 (71,820)
//! by 1,215, and the 7-row geometry is a construction, not a
//! measurement. If this test fails after regenerating, read the
//! generator header and data/README.md before touching the loader.
//! If the generator changes, update the constants here to match.

use helion_ultrascale::{ArchSummary, BitLocator, DeviceFile};
use std::path::PathBuf;

fn manifest_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn load() -> (DeviceFile, ArchSummary) {
    let data = manifest_dir().join("data");
    let device = DeviceFile::from_path(&data.join("xcvu3p.json")).unwrap();
    let arch = ArchSummary::from_path(&data.join("ULTRASCALE_PLUS.json")).unwrap();
    (device, arch)
}

#[test]
fn xcvu3p_is_provisional_with_header_counts() {
    let (device, _) = load();
    assert!(device.is_provisional());
    let notes = device.provisional_notes();
    assert!(!notes.is_empty());
    for note in notes {
        assert!(!note.field.is_empty(), "note with empty field");
        assert!(!note.value.is_empty(), "note with empty value");
        assert!(!note.source.is_empty(), "note with empty source");
    }
    // XMP103 published counts (see scripts/gen_xcvu3p.py).
    assert_eq!(device.num_slices(), 49_260);
    assert_eq!(device.num_luts(), 394_080);
    assert_eq!(device.num_regs(), 788_160);
    assert_eq!(device.num_brams(), 720);
    assert_eq!(device.num_dsps(), 2_280);
    assert_eq!(device.num_slrs(), 1);
    // UG570 Table 2, production revision 1 or later.
    assert_eq!(device.slr_idcode("SLR0").unwrap(), 0x14B3_9093);
    assert_eq!(device.max_far_row_idx("SLR0").unwrap(), 6);
}

#[test]
fn xcvu3p_structure_validates_and_frame_total_matches_generator() {
    let (device, _) = load();
    let checked = device
        .validate_structure()
        .expect("structure must validate");
    assert!(checked > 0);
    // Computed by scripts/gen_xcvu3p.py from the tables in the file.
    // UG570 Table 1 lists 71,820 for xcvu3p; this construction
    // overshoots by 1,215. Do not tune the constant to match UG570;
    // the overshoot is evidence about the construction.
    assert_eq!(device.total_frames(), 73_035);
}

#[test]
fn xcvu3p_locates_bels_across_all_rows() {
    let (device, arch) = load();
    let loc = BitLocator::new(&device, &arch);
    // First slice, first row.
    let (slr, fars, ofsts) = loc.locate_lut("SLICE_X0Y0/A6LUT").unwrap();
    assert_eq!(slr, "SLR0");
    assert_eq!(fars.len(), 64);
    assert_eq!(ofsts.len(), 64);
    // Last row (row 6, Y 419), last CLB column of a 118-column row.
    let (slr, fars, _) = loc.locate_lut("SLICE_X117Y419/A6LUT").unwrap();
    assert_eq!(slr, "SLR0");
    assert_eq!(fars.len(), 64);
    // A 117-column row (row 5, Y 359) at its last column.
    let (_, fars, _) = loc.locate_lut("SLICE_X116Y359/A6LUT").unwrap();
    assert_eq!(fars.len(), 64);
    // A FF in the middle of the die.
    let (slr, _, _) = loc.locate_reg("SLICE_X50Y200/BFF").unwrap();
    assert_eq!(slr, "SLR0");
    // BRAM: first site and last site (X 9, Y 167, row 6).
    let (slr, mem_fars, mem_ofsts, par_fars, par_ofsts) = loc.locate_bram("RAMB18_X0Y0").unwrap();
    assert_eq!(slr, "SLR0");
    assert_eq!(mem_fars.len(), 16384);
    assert_eq!(par_fars.len(), 2048);
    let _ = (mem_ofsts, par_ofsts);
    let (_, mem_fars, _, par_fars, _) = loc.locate_bram("RAMB18_X9Y167").unwrap();
    assert_eq!(mem_fars.len(), 16384);
    assert_eq!(par_fars.len(), 2048);
}
